#include <bits/stdc++.h>
using namespace std;
typedef vector<vector<int>> Grid;

// Siamese method: move up-right, or down when that cell is taken.
Grid odd(int n) {
    Grid a(n, vector<int>(n, 0));
    int r = 0, c = n / 2;
    for (int v = 1; v <= n * n; v++) {
        a[r][c] = v;
        int nr = (r - 1 + n) % n, nc = (c + 1) % n;
        if (a[nr][nc]) r = (r + 1) % n;
        else r = nr, c = nc;
    }
    return a;
}

Grid construct(int n) {
    if (n % 2) return odd(n);
    Grid a(n, vector<int>(n));
    if (n % 4 == 0) {
        // Doubly even: complement the cells on the 4x4 diagonal pattern.
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++) {
                int v = r * n + c + 1;
                a[r][c] = (r % 4 == c % 4 || r % 4 + c % 4 == 3) ? n * n + 1 - v : v;
            }
        return a;
    }
    // Singly even (LUX-style): four odd blocks offset by 0, 2m^2, 3m^2, m^2, then column swaps.
    int m = n / 2, k = (n - 2) / 4;
    Grid base = odd(m);
    for (int r = 0; r < n; r++)
        for (int c = 0; c < n; c++) {
            int q = r < m ? (c < m ? 0 : 2) : (c < m ? 3 : 1);
            a[r][c] = base[r % m][c % m] + q * m * m;
        }
    vector<int> cols;
    for (int c = 0; c < k; c++) cols.push_back(c);
    for (int c = n - k + 1; c < n; c++) cols.push_back(c);
    for (int r = 0; r < m; r++)
        for (int c : cols) swap(a[r][c], a[r + m][c]);
    for (int c : {0, k}) swap(a[k][c], a[k + m][c]);
    return a;
}

int main() {
    int n;
    if (scanf("%d", &n) != 1) return 0;
    if (n == 2) { puts("null"); return 0; }
    Grid a = construct(n);
    string out;
    for (auto &row : a) {
        for (int c = 0; c < n; c++) { if (c) out += ' '; out += to_string(row[c]); }
        out += '\n';
    }
    fputs(out.c_str(), stdout);
}

