        if (n % 2 == 1) return odd(n);
        int[][] a = new int[n][n];
        if (n % 4 == 0) {
            // Doubly even: complement the cells on the 4x4 diagonal pattern.
            for (int r = 0; r < n; r++)
                for (int c = 0; c < n; c++) {
                    int v = r * n + c + 1;
                    a[r][c] = (r % 4 == c % 4 || r % 4 + c % 4 == 3) ? n * n + 1 - v : v;
                }
            return a;
        }
        // Singly even (LUX-style): four odd blocks offset by 0, 2m^2, 3m^2, m^2, then column swaps.
        int m = n / 2, k = (n - 2) / 4;
        int[][] base = odd(m);
        for (int r = 0; r < n; r++)
            for (int c = 0; c < n; c++) {
                int q = r < m ? (c < m ? 0 : 2) : (c < m ? 3 : 1);
                a[r][c] = base[r % m][c % m] + q * m * m;
            }
        List<Integer> cols = new ArrayList<>();
        for (int c = 0; c < k; c++) cols.add(c);
        for (int c = n - k + 1; c < n; c++) cols.add(c);
