package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

// Siamese method: move up-right, or down when that cell is taken.
func odd(n int) [][]int {
	a := make([][]int, n)
	for i := range a {
		a[i] = make([]int, n)
	}
	r, c := 0, n/2
	for v := 1; v <= n*n; v++ {
		a[r][c] = v
		nr, nc := (r-1+n)%n, (c+1)%n
		if a[nr][nc] != 0 {
			r = (r + 1) % n
		} else {
			r, c = nr, nc
		}
	}
	return a
}

func construct(n int) [][]int {
	if n%2 == 1 {
		return odd(n)
	}
	a := make([][]int, n)
	for i := range a {
		a[i] = make([]int, n)
	}
	if n%4 == 0 {
		// Doubly even: complement the cells on the 4x4 diagonal pattern.
		for r := 0; r < n; r++ {
			for c := 0; c < n; c++ {
				v := r*n + c + 1
				if r%4 == c%4 || r%4+c%4 == 3 {
					v = n*n + 1 - v
				}
				a[r][c] = v
			}
		}
		return a
	}
	// Singly even (LUX-style): four odd blocks offset by 0, 2m^2, 3m^2, m^2, then column swaps.
	m, k := n/2, (n-2)/4
	base := odd(m)
	for r := 0; r < n; r++ {
		for c := 0; c < n; c++ {
			q := 0
			switch {
			case r < m && c >= m:
				q = 2
			case r >= m && c < m:
				q = 3
			case r >= m && c >= m:
				q = 1
			}
			a[r][c] = base[r%m][c%m] + q*m*m
		}
	}
	var cols []int
	for c := 0; c < k; c++ {
		cols = append(cols, c)
	}
	for c := n - k + 1; c < n; c++ {
		cols = append(cols, c)
	}
	for r := 0; r < m; r++ {
		for _, c := range cols {
			a[r][c], a[r+m][c] = a[r+m][c], a[r][c]
		}
	}
	for _, c := range []int{0, k} {
		a[k][c], a[k+m][c] = a[k+m][c], a[k][c]
	}
	return a
}

func main() {
	var n int
	fmt.Scan(&n)
	if n == 2 {
		fmt.Println("null")
		return
	}
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	for _, row := range construct(n) {
		for c, v := range row {
			if c > 0 {
				out.WriteByte(' ')
			}
			out.WriteString(strconv.Itoa(v))
		}
		out.WriteByte('\n')
	}
}
